def length_of_lis(nums):           # O(n^2) - correct, too slow
    best = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                best[i] = max(best[i], best[j] + 1)
    return max(best) if best else 0

import bisect


def length_of_lis(nums):
    tails = []
    for n in nums:
        # First index whose value is >= n. bisect_left, not bisect_right:
        # the subsequence must be strictly increasing, so an equal value
        # has to replace rather than extend.
        i = bisect.bisect_left(tails, n)
        if i == len(tails):
            tails.append(n)
        else:
            tails[i] = n
    return len(tails)

