function lengthOfLis(nums) {
  const tails = [];
  for (const n of nums) {
    // Hand-rolled lower_bound: first index whose value is >= n.
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < n) lo = mid + 1;
      else hi = mid;
    }
    if (lo === tails.length) tails.push(n);
    else tails[lo] = n;
  }
  return tails.length;
}

long long lengthOfLis(std::vector<long long> nums) {
    std::vector<long long> tails;
    for (std::size_t i = 0; i < nums.size(); ++i) {
        // lower_bound is >= (strictly increasing). upper_bound would be >,
        // which solves the non-decreasing variant instead.
        std::vector<long long>::iterator it =
            std::lower_bound(tails.begin(), tails.end(), nums[i]);
        if (it == tails.end()) tails.push_back(nums[i]);
        else *it = nums[i];
    }
    return (long long)tails.size();
}
